def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    blocks=[]
    for r in range(h-2):
        for c in range(w-2):
            color=grid[r][c]
            if color and all(grid[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                if not any(color==x and r==rr and c==cc for rr,cc,x in blocks): blocks.append((r,c,color))
    rays={}
    for r,c,color in blocks:
        for j in range(w): rays.setdefault((r+1,j),set()).add(color)
        for i in range(h): rays.setdefault((i,c+1),set()).add(color)
    for (i,j),colors in rays.items():
        out[i][j] = next(iter(colors)) if len(colors)==1 else 0
    return out
